style.css:
@-moz-document url-prefix("https://itch.io") {
html, body, #wrapper, #page {
        background-image: url("https://i.ytimg.com/vi/pGtjsTPQBf8/maxresdefault.jpg") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
        background-color: transparent !important;
    }

    @keyframes blinker {
        0% { background-color: #a4de02 !important; }
        50% { background-color: #bc13fe !important; }
        100% { background-color: #a4de02 !important; }
    }

    .main_header, .header, .header_user_menu, .top_menu, .main_menu, .nav_column {
        animation: blinker 1s linear infinite !important;
    }
}
